parts.text:
{
  "days": [
    {
      "day": 1,
      "title": "Arrivo e prime luci nel centro",
      "stops": [
        {
          "time": "AFTERNOON",
          "ref": "L1",
          "name": "Duomo di Santo Stefano",
          "activity": "Visita la splendida cattedrale gotica simbolo di Vienna.",
          "minutes": 90
        },
        {
          "time": "AFTERNOON",
          "ref": "",
          "name": "Café Central",
          "activity": "Fai una sosta in questo celebre caffè storico per gustare una fetta di torta Sacher.",
          "minutes": 60
        },
        {
          "time": "EVENING",
          "ref": "E2",
          "name": "Wiener Christkindlmarkt",
          "activity": "Vivi l'atmosfera natalizia di fronte al municipio con luci e vin brulè.",
          "minutes": 120
        }
      ],
      "tip": "Indossa scarpe comode per camminare nel centro storico acciottolato."
    },
    {
      "day": 2,
      "title": "Arte imperiale e mercatini storici",
      "stops": [
        {
          "time": "MORNING",
          "ref": "L2",
          "name": "Hofburg",
          "activity": "Esplora il vasto complesso del palazzo imperiale degli Asburgo.",
          "minutes": 150
        },
        {
          "time": "AFTERNOON",
          "ref": "L5",
          "name": "Kunsthistorisches Museum",
          "activity": "Ammira i capolavori della pittura europea in un museo straordinario.",
          "minutes": 150
        },
        {
          "time": "EVENING",
          "ref": "E1",
          "name": "Weihnachtsmarkt am Spittelberg",
          "activity": "Passeggia tra i vicoli del mercatino famoso per l'artigianato locale.",
          "minutes": 90
        }
      ],
      "tip": "Acquista i biglietti dei musei in anticipo online per evitare le code."
    },
    {
      "day": 3,
      "title": "Capolavori barocchi e sapori tipici",
      "stops": [
        {
          "time": "MORNING",
          "ref": "L4",
          "name": "Belvedere",
          "activity": "Visita il museo e ammira opere iconiche come Il Bacio di Klimt.",
          "minutes": 150
        },
        {
          "time": "AFTERNOON",
          "ref": "L8",
          "name": "Naschmarkt",
          "activity": "Assaggia le specialità gastronomiche locali tra le bancarelle del mercato.",
          "minutes": 90
        },
        {
          "time": "EVENING",
          "ref": "L10",
          "name": "Wiener Staatsoper",
          "activity": "Osserva la maestosa facciata del teatro dell'opera illuminata la sera.",
          "minutes": 45
        }
      ],
      "tip": "Al Naschmarkt prova i formaggi austriaci e i falafel caldi."
    },
    {
      "day": 4,
      "title": "Residenze imperiali e architetture uniche",
      "stops": [
        {
          "time": "MORNING",
          "ref": "L3",
          "name": "Castello di Schönbrunn",
          "activity": "Visita gli appartamenti reali della residenza estiva degli Asburgo.",
          "minutes": 150
        },
        {
          "time": "AFTERNOON",
          "ref": "E3",
          "name": "Weihnachtsmarkt Schloss Schönbrunn",
          "activity": "Goditi il mercatino di Natale situato nella splendida corte del castello.",
          "minutes": 90
        },
        {
          "time": "AFTERNOON",
          "ref": "L11",
          "name": "Hundertwasserhaus",
          "activity": "Fotografa il colorato e irregolare condominio progettato da Hundertwasser.",
          "minutes": 45
        }
      ],
      "tip": "Prendi la metropolitana per spostarti rapidamente tra Schönbrunn e il centro."
    },
    {
      "day": 5,
      "title": "Ultimi sguardi e partenza",
      "stops": [
        {
          "time": "MORNING",
          "ref": "L6",
          "name": "Albertina",
          "activity": "Visita le collezioni di arti grafiche e moderne prima della partenza.",
          "minutes": 120
        }
      ],
      "tip": "Controlla gli orari dei mezzi per raggiungere l'aeroporto in tempo."
    }
  ],
  "packing": [
    {
      "category": "Abbigliamento invernale",
      "items": [
        "Cappotto pesante",
        "Maglioni di lana",
        "Sciarpa, guanti e berretto",
        "Scarpe impermeabili e comode"
      ]
    },
    {
      "category": "Altro",
      "items": [
        "Ombrello compatto",
        "Adattatore per prese elettriche",
        "Documenti di identità"
      ]
    }
  ],
  "tips": [
    "Usa la metropolitana U-Bahn per muoverti in modo efficiente in città.",
    "Nei ristoranti è usanza lasciare una mancia del 5-10% se il servizio è gradito.",
    "Fai attenzione ai tuoi effetti personali nei luoghi affollati come i mercatini di Natale."
  ]
}
